/* @autogenerated */
/**
 * Core Web Vitals sin dependencias, con `PerformanceObserver`: LCP, CLS, INP (aproximado: la
 * interacción más lenta), FCP y TTFB. Cada métrica se informa una vez, al ocultar la página (o al
 * llegar, la de TTFB y FCP), con su valoración según los umbrales de web.dev.
 */
export interface WebVital {
  name: 'LCP' | 'CLS' | 'INP' | 'FCP' | 'TTFB';
  /** Milisegundos; CLS sin unidad. */
  value: number;
  rating: 'good' | 'needs-improvement' | 'poor';
  /** Ruta de la página, sin query ni hash (el back sustituye los ids por `:id`). */
  route: string;
}

const THRESHOLDS: Record<WebVital['name'], [number, number]> = {
  LCP: [2500, 4000],
  CLS: [0.1, 0.25],
  INP: [200, 500],
  FCP: [1800, 3000],
  TTFB: [800, 1800],
};

function rating(name: WebVital['name'], value: number): WebVital['rating'] {
  const [good, poor] = THRESHOLDS[name];
  return value <= good ? 'good' : value <= poor ? 'needs-improvement' : 'poor';
}

function observe(
  type: string,
  callback: (entries: PerformanceEntryList) => void,
  options: Record<string, unknown> = {},
) {
  try {
    if (!PerformanceObserver.supportedEntryTypes?.includes(type)) return;
    new PerformanceObserver((list) => callback(list.getEntries())).observe({
      type,
      buffered: true,
      ...options,
    } as PerformanceObserverInit);
  } catch {
    // Navegador sin soporte: esa métrica no se mide
  }
}

export function startWebVitals(report: (vital: WebVital) => void): void {
  if (typeof PerformanceObserver === 'undefined') return;
  const route = () => location.pathname;
  const send = (name: WebVital['name'], value: number) =>
    report({
      name,
      value: Math.round(name === 'CLS' ? value * 1000 : value) / (name === 'CLS' ? 1000 : 1),
      rating: rating(name, value),
      route: route(),
    });

  const navigation = performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming | undefined;
  if (navigation) send('TTFB', navigation.responseStart);
  observe('paint', (entries) => {
    const fcp = entries.find((entry) => entry.name === 'first-contentful-paint');
    if (fcp) send('FCP', fcp.startTime);
  });

  let lcp = 0;
  let cls = 0;
  let inp = 0;
  observe('largest-contentful-paint', (entries) => {
    const last = entries[entries.length - 1];
    if (last) lcp = last.startTime;
  });
  observe('layout-shift', (entries) => {
    for (const entry of entries as unknown as { value: number; hadRecentInput: boolean }[]) {
      if (!entry.hadRecentInput) cls += entry.value;
    }
  });
  observe(
    'event',
    (entries) => {
      for (const entry of entries) inp = Math.max(inp, entry.duration);
    },
    { durationThreshold: 40 },
  );

  let reported = false;
  const flush = () => {
    if (reported) return;
    reported = true;
    if (lcp) send('LCP', lcp);
    send('CLS', cls);
    if (inp) send('INP', inp);
  };
  addEventListener(
    'visibilitychange',
    () => {
      if (document.visibilityState === 'hidden') flush();
    },
    { once: false },
  );
  addEventListener('pagehide', flush, { once: true });
}
